<script setup lang="ts">
import type { ExportEntry } from '~/types/exports'
import { formatInfo, exportLabels, formatSize, unavailableReason } from '~/utils/export-data'
defineProps<{ entries: ExportEntry[]; version: number; busy?: boolean }>()
defineEmits<{ download: [id: string]; show: [id: string]; refresh: [] }>()
function date(value: string | null) { if (!value) return 'Не указано'; const parsed=new Date(value); return Number.isNaN(parsed.valueOf())?'Дата не распознана':parsed.toLocaleString('ru-RU') }
</script>
<template><section class="export-history" aria-labelledby="export-history-heading"><div class="export-actions"><h3 id="export-history-heading">История экспортов · версия {{ version }}</h3><UiButton variant="secondary" :disabled="busy" @click="$emit('refresh')">Обновить историю</UiButton></div><p>Доступность поступает с сервера и может измениться после отзыва источника или повторной проверки.</p><UiState v-if="!entries.length" kind="empty" title="Экспортов этой ревизии пока нет" /><article v-for="entry in entries" :key="entry.id" class="export-history-item"><div class="export-actions"><strong>{{ formatInfo[entry.format].title }}</strong><UiBadge :tone="entry.status==='ready'?'success':entry.status==='failed'?'warning':'neutral'">{{ exportLabels[entry.status] }}</UiBadge></div><dl><div><dt>Создан</dt><dd>{{ date(entry.created_at) }}</dd></div><div><dt>Завершён</dt><dd>{{ date(entry.completed_at) }}</dd></div><div><dt>Файл</dt><dd>{{ entry.artifact?.file_name ?? 'Артефакт ещё не получен' }}</dd></div><div v-if="entry.artifact"><dt>Размер</dt><dd>{{ formatSize(entry.artifact.file_size_bytes) }}</dd></div></dl><p v-if="unavailableReason(entry)" class="text-warning">{{ unavailableReason(entry) }}</p><div class="export-actions"><UiButton :disabled="busy || !entry.is_downloadable || entry.status!=='ready' || !entry.artifact" @click="$emit('download',entry.id)">Скачать</UiButton><UiButton variant="secondary" :disabled="busy" @click="$emit('show',entry.id)">Состояние задания</UiButton></div></article></section></template>
